import React from 'react';
import { createPortal } from 'react-dom';
import { CampaignWidget } from '../../types';
import { useCampaignsList } from '../../hooks/useCampaigns';
import trackEvent from '../../core/trackEvent';

// Separate component for each widget to avoid hook issues
const WidgetItem: React.FC<{ data: CampaignWidget }> = ({ data }) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const { details } = data;
  const styling = details.styling || {};
  const images = details.widget_images || [];

  const widgetType = details.type || styling.type || 'full';
  const isHalf = widgetType === 'half';
  const showCarousel = isHalf ? images.length > 2 : images.length > 1;

  React.useEffect(() => {
    void trackEvent('widget_viewed', data.id);
  }, [data.id]);

  const containerStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'row',
    flexWrap: showCarousel ? 'nowrap' : 'wrap',
    gap: '12px',
    width: '100%',
    height: isHalf ? (details.height ? `${details.height}px` : 'auto') : 'auto',
    marginTop: styling.topMargin ? `${styling.topMargin}px` : '0px',
    marginBottom: styling.bottomMargin ? `${styling.bottomMargin}px` : '0px',
    marginLeft: styling.leftMargin ? `${styling.leftMargin}px` : '8px',
    marginRight: styling.rightMargin ? `${styling.rightMargin}px` : '8px',
    boxSizing: 'border-box',
    overflowX: showCarousel ? 'auto' : 'hidden',
    overflowY: 'hidden',
    scrollSnapType: showCarousel ? 'x mandatory' : undefined,
    msOverflowStyle: 'none',
    scrollbarWidth: 'none',
  };

  const handleScroll = () => {
    if (containerRef.current) {
      const { scrollLeft, offsetWidth } = containerRef.current;
      const itemWidth = isHalf ? (offsetWidth / 2) + 6 : offsetWidth + 12;
      const index = Math.round(scrollLeft / itemWidth);
      setActiveIndex(index);
    }
  };

  const handleClick = (imageId: string, link: string) => {
    void trackEvent('widget_clicked', data.id, { image_id: imageId });
    if (link) {
      if (link.startsWith('http')) {
        window.open(link, '_blank');
      } else {
        console.log('Internal link:', link);
      }
    }
  };

  // Find portal target
  const pos = data.position || '';
  const key = pos ? String(pos).replace(/^widget_/, '') : '';
  const selectors = key ? [
    `[data-as-id="${key}"]`,
    `#${key}`,
    `.${key}`,
    `[data-widget="${key}"]`,
  ] : [];

  let target: Element | null = null;
  try {
    for (const sel of selectors) {
      const el = document.querySelector(sel);
      if (el) {
        console.log('[WidgetItem] Portal target found:', sel, el);
        target = el;
        break;
      }
    }
    if (!target && selectors.length > 0) {
      console.warn('[WidgetItem] No portal target found for position:', data.position, 'selectors:', selectors);
    }
  } catch (e) {
    console.error('[WidgetItem] Portal lookup error:', e);
  }

  const content = (
    <div key={data.id} style={{ width: '100%', position: 'relative' }}>
      <style>{`
        .widget-scroll-container::-webkit-scrollbar {
          display: none;
        }
      `}</style>
      <div
        ref={containerRef}
        className="widget-scroll-container"
        style={containerStyle}
        onScroll={showCarousel ? handleScroll : undefined}
      >
        {images.map((img) => {
          const itemStyle: React.CSSProperties = {
            flex: isHalf ? '0 0 calc(50% - 6px)' : '0 0 100%',
            height: isHalf ? '100%' : 'auto',
            cursor: img.link ? 'pointer' : 'default',
            position: 'relative',
            overflow: 'hidden',
            borderRadius: styling.borderRadius ? `${styling.borderRadius}px` : '0px',
            borderTopLeftRadius: styling.topLeftRadius ? `${styling.topLeftRadius}px` : undefined,
            borderTopRightRadius: styling.topRightRadius ? `${styling.topRightRadius}px` : undefined,
            borderBottomLeftRadius: styling.bottomLeftRadius ? `${styling.bottomLeftRadius}px` : undefined,
            borderBottomRightRadius: styling.bottomRightRadius ? `${styling.bottomRightRadius}px` : undefined,
            boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
            scrollSnapAlign: 'start',
          };

          const imgStyle: React.CSSProperties = {
            width: '100%',
            height: isHalf ? '100%' : 'auto',
            objectFit: 'cover',
            display: 'block',
          };

          const imageUrl = img.image && img.image.startsWith && img.image.startsWith('https://appstorysmediabucketdev.s3.ap-south-1.amazonaws.com/https://')
            ? img.image.replace('https://appstorysmediabucketdev.s3.ap-south-1.amazonaws.com/https://', 'https://')
            : img.image;

          return (
            <div
              key={img.id}
              style={itemStyle}
              onClick={() => handleClick(img.id, img.link)}
            >
              <img
                src={imageUrl}
                alt={`Widget item`}
                style={imgStyle}
              />
            </div>
          );
        })}
      </div>

      {showCarousel && (
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '6px',
          marginTop: '8px',
          width: '100%'
        }}>
          {images.map((_, i) => (
            <div
              key={i}
              style={{
                width: '6px',
                height: '6px',
                borderRadius: '50%',
                backgroundColor: i === activeIndex ? '#333' : '#ccc',
                transition: 'background-color 0.2s ease',
              }}
            />
          ))}
        </div>
      )}
    </div>
  );

  if (target) {
    console.log('[WidgetItem] Rendering into portal target');
    return createPortal(content, target);
  }
  console.log('[WidgetItem] No portal target, rendering inline');
  return content;
};

export const Widget: React.FC = () => {
  const dataList = useCampaignsList<CampaignWidget>('WID', { screenContains: 'home' });

  React.useEffect(() => {
    if (dataList && dataList.length > 0) {
      console.log('[Widget] Found', dataList.length, 'WID campaigns:', dataList.map(d => ({ id: d.id, position: d.position, screen: d.screen })));
    }
  }, [dataList]);

  if (!dataList || dataList.length === 0) {
    console.log('[Widget] No WID campaigns found');
    return null;
  }

  return (
    <>
      {dataList.map((d) => (
        <WidgetItem key={d.id} data={d} />
      ))}
    </>
  );
};
